[InitializeOnLoad]public static class ContinuousGapVerify{static ContinuousGapVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("ContinuousGapVerify.request"))return;File.Delete("ContinuousGapVerify.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");var f=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name.ToLower().Contains("beach promenade sidewalk joins"));var c=f.GetComponent<MeshCollider>();c.sharedMesh=null;c.sharedMesh=f.sharedMesh;Physics.SyncTransforms();int[] covered=new int[5];for(int x=0;x<5;x++)for(int z=-180;z<=180;z+=6){RaycastHit hit;if(c.Raycast(new Ray(new Vector3(146+x*1.5f,100,z),Vector3.down),out hit,150))covered[x]++;}typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,new Vector3(141.43f,36.25f,-83.49f),new Vector3(127.34f,2.14f,-4.63f),"Filled-Canal-Promenade-Gap"});EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText("FinalEnvironmentRoadReview/ContinuousGapVerify.txt","Join renderer/collider count=1; recooked collision; ray coverage at X146/147.5/149/150.5/152 (61 samples each)="+string.Join(",",covered)+"; shader errors="+ShaderUtil.GetShaderMessages(f.GetComponent<Renderer>().sharedMaterial.shader).Count(m=>m.severity.ToString()=="Error"));}}
